const particles=[];const N=70;for(let i=0;i<N;i++){particles.push({x:Math.random()*W(),y:H()+Math.random()*H()*0.5,r:1+Math.random()*2.2,speed:0.15+Math.random()*0.35,drift:Math.random()*0.02+0.005,phase:Math.random()*Math.PI*2,hueIdx:Math.floor(Math.random()*PALETTE.length),tail:[]});}
function hexToRgb(h){h=h.replace('#','');const n=parseInt(h,16);return[(n>>16)&255,(n>>8)&255,n&255];}
const rgbs=PALETTE.map(hexToRgb);
let t=0;
function frame(){
 t+=0.01;
 const w=W(),h=H();
 ctx.clearRect(0,0,w,h);
 // soft glow blobs top and bottom corners, avoiding center
 function blob(x,y,r,rgb,alpha){
  const g=ctx.createRadialGradient(x,y,0,x,y,r);
  g.addColorStop(0,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha})`);
  g.addColorStop(1,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},0)`);
  ctx.fillStyle=g;
  ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();
 }
 blob(w*0.18, h*0.86 + Math.sin(t*0.6)*8, w*0.32, rgbs[1], 0.10);
 blob(w*0.82, h*0.12 + Math.cos(t*0.5)*6, w*0.28, rgbs[0], 0.08);

 for(const p of particles){
  p.y -= p.speed;
  p.x += Math.sin(t*2+p.phase)*p.drift*20;
  if(p.y < -10){ p.y = h + 10; p.x = Math.random()*w; }
  p.tail.push({x:p.x,y:p.y});
  if(p.tail.length>10) p.tail.shift();
  const rgb=rgbs[p.hueIdx];
  // skip drawing near exact center to keep it calm
  const dx=p.x-w/2, dy=p.y-h/2;
  const distCenter=Math.sqrt(dx*dx+dy*dy);
  const centerFade = distCenter < w*0.28 ? 0.25 : 1;
  for(let i=0;i<p.tail.length;i++){
   const pt=p.tail[i];
   const a=(i/p.tail.length)*0.5*centerFade;
   ctx.beginPath();
   ctx.fillStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},${a})`;
   ctx.arc(pt.x,pt.y,p.r*(i/p.tail.length),0,Math.PI*2);
   ctx.fill();
  }
  ctx.save();
  ctx.shadowBlur=8;
  ctx.shadowColor=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},0.8)`;
  ctx.beginPath();
  ctx.fillStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},${0.7*centerFade})`;
  ctx.arc(p.x,p.y,p.r,0,Math.PI*2);
  ctx.fill();
  ctx.restore();
 }
 requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
